def gen(rng):
    import itertools
    tests = ['1 2 3', '5 5 5', '-1 -1 -1', '0 0 0', '1000000000 -1000000000 0', '-1000000000 -1000000000 -999999999',
             '1000000000 1000000000 1000000000', '-1000000000 -1000000000 -1000000000']
    for p in itertools.permutations([-4, 0, 9]):
        tests.append(' '.join(map(str, p)))
    for p in itertools.permutations([6, 6, 2]):
        tests.append(' '.join(map(str, p)))
    for _ in range(12):
        tests.append(' '.join(str(rng.randint(-20, 20)) for _ in range(3)))
    for _ in range(6):
        tests.append(' '.join(str(rng.randint(-10**9, 10**9)) for _ in range(3)))
    tests.append('\n'.join(str(rng.randint(-10**9, 10**9)) for _ in range(3)))
    return tests

